  }
  .btn-primary { @apply bg-blue-600 text-white hover:bg-blue-700; }
  .btn-secondary { @apply border border-slate-300 bg-white text-slate-800 hover:bg-slate-50 dark:border-slate-600 dark:bg-slate-800 dark:text-slate-100 dark:hover:bg-slate-700; }
